// Keep the original tuned ThinkingOrb wrapper and only scale its 64px canvas for different surfaces.
function Orb({ px = 40, state = "composing" as OrbState, speed = 1, paused = false }: { px?: number; state?: OrbState; speed?: number; paused?: boolean }) {
  const [reduced, setReduced] = useState(false);
  useEffect(() => { const query = window.matchMedia("(prefers-reduced-motion: reduce)"); const sync = () => setReduced(query.matches); sync(); query.addEventListener?.("change", sync); return () => query.removeEventListener?.("change", sync); }, []);
  const scale = px / 64;
  return <div style={{ width: px, height: px, flexShrink: 0, overflow: "hidden" }}><div style={{ width: 64, height: 64, transform: `scale(${scale})`, transformOrigin: "top left" }}><ThinkingOrb state={state} size={64} theme="light" speed={speed} paused={paused || reduced} /></div></div>;
}
